// 本人办理页只测有限来源、原命令与误认拒绝；纯读夹具不冒S5真实邀约或工资结算。
#include "resident/domains/tasks/task_employment_view.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0;
// 具名断言区分未授权来源、分页和真实参数，不累计普通UI矩阵。
void need(bool value,const char* reason){++checks;if(!value)throw std::runtime_error(reason);}
struct Read final:EstateEmploymentRead {
    std::vector<StableId> ids{"employment:1"};EstateEmploymentSource source;std::vector<EstateEmploymentPolicySource> policies;mutable Integer policy_calls=0;bool hidden=false;
    // 测试替身只返回本次固定源，不执行合同接受或支付。
    Outcome<std::optional<EstateEmploymentSource>> estate_employment_source(const StableId&,const StableId&)const override{return {true,hidden?std::optional<EstateEmploymentSource>{}:std::optional<EstateEmploymentSource>{source},{}};}
    Outcome<std::vector<StableId>> estate_employment_contract_ids(const StableId&,Integer,Integer limit)const override{need(limit==16,"page asks bounded sixteen original IDs");return {true,ids,{}};}
    Outcome<std::vector<EstateEmploymentPolicySource>> estate_employment_policies(const StableId&,const StableId&)const override{++policy_calls;return {true,policies,{}};}
};
}
int main(){try{
    CommonState state;state.identity.tick=1;state.metadata.player_actor_id="worker";CommonCatalog catalog;
    for(const auto& id:{"worker","employer"}){ActorRecord actor;actor.id=id;actor.alive=true;actor.available=true;actor.location=SettlementLocation{"town","estate"};state.actors.insert(id,actor);catalog.actor_names.insert(id,{id,{},{}});catalog.texts.insert(id,id);}
    CommonStore common(state,std::make_shared<CommonCatalog>(catalog));InteractionState interaction;Read read;auto& source=read.source;source.source_identity=state.identity;source.observer_actor_id="worker";source.contract_id="employment:1";source.status="offered";source.observed_tick=1;source.terms.employer_actor_id="employer";source.terms.worker_actor_id="worker";source.terms.job="farm";source.terms.wage_numerator=3;source.terms.wage_denominator=2;source.terms.service_ticks=4;source.terms.reservation_cap=6;
    bool reject=false,bad_echo=false;std::vector<EstateEmploymentCommand> requested;
    TaskEmploymentPreview preview=[&](const StableId& actor,const EstateEmploymentCommand& command)->Outcome<EstateEmploymentQuote>{requested.push_back(command);if(reject)return {false,{},common_failure("EmploymentWorkerOccupied").error};EstateEmploymentQuote quote;quote.source_identity=common.state().identity;quote.actor_id=actor;quote.command=bad_echo?EstateEmploymentCommand{EstateEmploymentDecision{"other","accept"}}:command;return {true,quote,{}};};
    const auto query=[&](Integer cursor=0,Integer policy_cursor=0){return query_task_employment(common,catalog,interaction,read,preview,cursor,policy_cursor);};
    auto before=encode_common_state(common.state());auto page=query();need(page.ok,"own offered contract visible");need(read.policy_calls==0,"no conversation never asks for all employment policies");need(requested.size()==2&&std::get<EstateEmploymentDecision>(requested[0]).decision=="accept"&&std::get<EstateEmploymentDecision>(requested[1]).decision=="decline","worker receives only own original accept and decline commands");need(compare_boundary(before,encode_common_state(common.state())).exact(),"query leaves assets facts rng and revision unchanged");
    reject=true;page=query();need(page.ok,"ordinary original preview refusal remains visible");const auto& rows=boundary::array(boundary::field(page.value,"rows","page"),"rows");const auto& actions=boundary::array(boundary::field(rows[0],"actions","row"),"actions");need(!boundary::get_bool(actions[0],"available","action")&&boundary::get_string(actions[0],"code","action")=="EmploymentWorkerOccupied","button keeps exact original refusal code");reject=false;bad_echo=true;need(!query().ok,"quote of another contract cannot enable original button");bad_echo=false;
    source.source_identity.execution_epoch+=1;need(!query().ok,"wrong restore epoch source refused");source.source_identity=common.state().identity;source.observer_actor_id="other";need(!query().ok,"another observer source refused");source.observer_actor_id="worker";read.hidden=true;need(!query().ok,"index cannot expose unauthorised hidden contract");read.hidden=false;read.ids.push_back("employment:1");need(!query().ok,"duplicate indexed contract refused");read.ids={"employment:1"};
    source.status="active";requested.clear();page=query();need(page.ok&&requested.size()==1&&std::get<EstateEmploymentDecision>(requested[0]).decision=="leave","only worker's own leave intent shown");source.status="leave";source.earned_cash=5;source.paid_cash=2;requested.clear();page=query();need(page.ok&&requested.empty(),"terminated employment keeps unpaid wages without new acceptance");source.paid_cash=6;need(!query().ok,"inconsistent paid and earned source rejected");source.paid_cash=2;
    common.state().metadata.player_actor_id="employer";source.observer_actor_id="employer";source.status="offered";requested.clear();page=query();need(page.ok&&requested.size()==1&&std::get<EstateEmploymentDecision>(requested[0]).decision=="withdraw","employer cannot accept for worker");source.status="active";requested.clear();page=query();need(page.ok&&std::get<EstateEmploymentDecision>(requested[0]).decision=="dismiss","employer sees original dismissal command");
    source.status="offered";InteractionSession meeting;meeting.actor_id="employer";meeting.phase="say";meeting.context.provider_actor_id="worker";meeting.context.place_id="estate";interaction.interactions.push_back(meeting);EstateEmploymentPolicySource policy;policy.source_identity=common.state().identity;policy.observer_actor_id="employer";policy.provider_actor_id="worker";policy.policy_id="farm_job";policy.employer_actor_id="employer";policy.worker_actor_id="worker";policy.job="farm";policy.wage_numerator=3;policy.wage_denominator=2;policy.service_ticks=4;policy.offer_valid_ticks=3;policy.reservation_cap=6;read.policies.push_back(policy);requested.clear();page=query();need(page.ok&&std::holds_alternative<EstateEmploymentOffer>(requested.back())&&std::get<EstateEmploymentOffer>(requested.back()).worker_actor_id=="worker","offer names actual current meeting worker only");need(std::any_of(requested.begin(),requested.end(),[](const EstateEmploymentCommand& cmd){const auto* decision=std::get_if<EstateEmploymentDecision>(&cmd);return decision&&decision->decision=="request_reply";}),"employer can only ask worker declaration without choosing its answer");
    common.state().metadata.player_actor_id="worker";source.observer_actor_id="worker";interaction.interactions[0].actor_id="worker";interaction.interactions[0].context.provider_actor_id="employer";read.policies[0].observer_actor_id="worker";read.policies[0].provider_actor_id="employer";read.policies[0].provider_offer=true;requested.clear();page=query();need(page.ok&&std::holds_alternative<EstateEmploymentRequestOffer>(requested.back()),"worker requests employer's own offer without accepting it");need(std::get<EstateEmploymentRequestOffer>(requested.back()).policy_id=="farm_job","request offer carries only original policy identity");read.policies[0].worker_actor_id="someone_else";need(!query().ok,"another intended worker cannot be substituted");
    common.state().metadata.player_actor_id="employer";source.observer_actor_id="employer";interaction.interactions[0]=meeting;read.policies[0]=policy;read.policies[0].provider_actor_id="remote";need(!query().ok,"remote policy cannot replace actual provider");read.policies[0]=policy;need(!query(0,2).ok,"policy cursor past real finite list rejected");interaction.interactions.clear();need(!query(0,1).ok,"old conversation policy cursor cannot survive close");need(!query(-1).ok,"negative contract cursor refused");
    std::cout<<checks<<" employment view necessary identity and command gates, 0 failures\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
